import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const checked = '2026-09-03';
const s=(id,label,url,note)=>({id,label,url,note});
const n=(id,name,parent,lineage,note,hook,tags,sourceIds,type='engine',year='current')=>({id,name,year,type,lineage,parent,note,hook,tags,sourceIds,verifiedOn:checked});
const e=(source,target,type,note)=>({source,target,type,...(note?{note}:{})});
function enrich(file, expansion){
  const p=path.join(root,'data','lineages',file); const d=JSON.parse(fs.readFileSync(p,'utf8').replace(/^\uFEFF/,''));
  d.sources ||= []; d.nodes ||= []; d.edges ||= [];
  const ss=new Set(d.sources.map(x=>x.id)); for(const x of expansion.sources||[]) if(!ss.has(x.id)){d.sources.push(x);ss.add(x.id)}
  const ns=new Set(d.nodes.map(x=>x.id)); for(const x of expansion.nodes||[]) if(!ns.has(x.id)){d.nodes.push(x);ns.add(x.id)}
  const es=new Set(d.edges.map(x=>`${x.source}|${x.target}|${x.type||''}`)); for(const x of expansion.edges||[]){const k=`${x.source}|${x.target}|${x.type||''}`;if(!es.has(k)){d.edges.push(x);es.add(k)}}
  fs.writeFileSync(p,JSON.stringify(d,null,2)+'\n'); console.log(`enriched ${d.id}: ${d.nodes.length} nodes, ${d.edges.length} edges, ${d.sources.length} sources`);
}

